forms={
 'a': lambda p: p[0]*A**p[1]*np.exp(-p[2]*np.sqrt(t))+p[3]*A**p[4]*np.exp(-p[5]*np.sqrt(t)),
 'b': lambda p: p[0]*A**p[1]*t**p[2]/(1+p[3]*np.sqrt(t)),
 'c': lambda p: p[0]*A**p[1]*np.sqrt(t)*np.exp(-p[2]*A)+p[3]*A**p[4]*t**p[5],
 'd': lambda p: (p[0]*A**p[1]+p[2]*A**p[3]*t**p[4])*np.exp(-p[5]*t),
 'f': lambda p: p[0]*A**p[1]*t**p[2]*np.exp(-p[3]*t/A),
}
for k,f in forms.items():
    best=None
    for s in range(25):
        p0=np.random.RandomState(s).uniform(-1,2,6)
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda p: np.nan_to_num(f(p)-dA_dt,nan=1e6,posinf=1e6,neginf=-1e6), p0)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
